  const lineSum=(row.shipment_items||[]).reduce((sum,item)=>sum+Number(item.line_total||0),0).toFixed(2);
  const fieldScores=docs.flatMap(d=>Object.values(d.field_confidence||{})).map(Number).filter(Number.isFinite);
  const orderedItems=[...(row.shipment_items||[])].sort((a,b)=>a.line_number-b.line_number);
  const invoiceDoc=docs.find(d=>d.document_type==='invoice');
  const approvalEvents=[...(row.shipment_approval_events||[])].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));
  const s={dbId:row.id,id:row.shipment_no,supplier:row.supplier_name||'Supplier not entered',port:row.port_name||'Nhava Sheva',date:row.shipment_date?new Date(`${row.shipment_date}T00:00:00`).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'—',status:statusLabel[row.status]||'In progress',documents:docs,docs:[...new Set(docs.map(d=>d.label))],lineItems:orderedItems,items:orderedItems.length,confidence:fieldScores.length?Math.round(fieldScores.reduce((a,b)=>a+b,0)/fieldScores.length):0,fieldConfidence:invoiceDoc?.field_confidence||{},fieldEvidence:invoiceDoc?.extracted_data?._evidence||{},invoice:row.invoice_number||'—',currency:row.currency||'USD',incoterm:row.incoterm||'—',packages:row.package_count==null?'—':`${row.package_count} ${row.package_type||'packages'}`,gross:row.gross_weight_kg==null?'—':`${row.gross_weight_kg} kg`,net:row.net_weight_kg==null?'—':`${row.net_weight_kg} kg`,container:(row.container_numbers||[]).join(', ')||'—',total:row.invoice_total==null?'':Number(row.invoice_total).toFixed(2),lineSum,itemQuantity:firstItem.quantity??0,itemUnitPrice:firstItem.unit_price??0,itemLineTotal:firstItem.line_total??0,invoiceGross:docs.find(d=>d.document_type==='invoice')?.facts.gross_weight_kg??'—',packingGross:docs.find(d=>d.document_type==='packing_list')?.facts.gross_weight_kg??'—',blGross:docs.find(d=>d.document_type==='bill_of_lading')?.facts.gross_weight_kg??'—',invoicePackages:docs.find(d=>d.document_type==='invoice')?.facts.package_count??'—',packingPackages:docs.find(d=>d.document_type==='packing_list')?.facts.package_count??'—',blPackages:docs.find(d=>d.document_type==='bill_of_lading')?.facts.package_count??'—',product:firstItem.description||'Line item not entered',qty:firstItem.quantity??'',unit:firstItem.unit_price??'',hsn:firstItem.hsn_code||'',itemId:firstItem.id,flag:'',reviewRequired:row.review_required_fields||[],confirmedFields:row.confirmed_fields||[]};
  if(docs.length<3)s.flag=`${3-docs.length} shipment document${docs.length===2?'':'s'} still missing.`;
  else if(s.status==='Needs review'){const failed=reconcileShipment(s).find(c=>!c.ok);s.flag=failed?.detail||'Review extracted fields before submission.'}
  s.executiveName=submitterProfile?.full_name||'Documentation executive';s.executiveCode=submitterProfile?.staff_code||'ID pending';
  s.approvalEvents=approvalEvents;s.latestApprovalEvent=approvalEvents[0]||null;
