  const submitForApproval=async()=>{if(role!=='Executive'){notify('Use the manager role to approve this shipment.');return}await pendingFieldSave.current;const currentShipment=isSupabaseConfigured?await refreshShipment(shipment.dbId):shipment;if(!canSubmitForApproval(currentShipment)){notify(approvalBlockers(currentShipment).slice(0,3).join(' '),6500);return}if(isSupabaseConfigured){const {data:saved,error:readError}=await supabase.from('shipments').select('supplier_name,invoice_number,currency,incoterm').eq('id',currentShipment.dbId).single();if(readError){notify(`Could not verify saved shipment fields: ${readError.message}`,6000);return}const required=[['Supplier','supplier_name'],['Invoice number','invoice_number'],['Currency','currency'],['Incoterm','incoterm']];const missing=required.filter(([,key])=>!String(saved?.[key]??'').trim());if(missing.length){notify(`Saved shipment is missing: ${missing.map(([label])=>label).join(', ')}. Re-enter the value and click outside the field to save it.`,6500);document.querySelector(`[aria-label="${missing[0][0]}"]`)?.scrollIntoView({behavior:'smooth',block:'center'});return}const {error}=await supabase.rpc('submit_shipment_for_approval',{p_shipment_id:currentShipment.dbId});if(error){notify(/confirm supplier, invoice number, currency and incoterm/i.test(error.message)?'Required values are saved, but Supabase rejected them. Refresh the app; if it continues, run migration 202611030003_manager_approval_workflow.sql in Supabase SQL Editor.':`Submission blocked: ${error.message}`,6500);return}}else recordStatus(shipment.status,'Ready to approve');persist(rows.map(s=>s.id===currentShipment.id?{...currentShipment,status:'Ready to approve',flag:''}:s));notify(`${currentShipment.id} submitted. Manager approval is now required.`)};
  const decideShipment=async(decision,note='')=>{if(role!=='Manager'||shipment?.status!=='Ready to approve'){notify('Select a shipment awaiting manager review.');return}if(decision!=='approved'&&!note.trim()){notify('Add a reason for the executive before returning or rejecting.');return}if(isSupabaseConfigured){setDecisionSaving(true);const {error}=await supabase.rpc('manager_decide_shipment',{p_shipment_id:shipment.dbId,p_decision:decision,p_note:note.trim()||null});setDecisionSaving(false);if(error){notify(`Decision was not saved: ${error.message}`,6000);return}await refreshShipment(shipment.dbId)}else{const nextStatus=decision==='approved'?'Approved':decision==='rejected'?'Rejected':'Returned for correction';recordStatus(shipment.status,nextStatus);persist(rows.map(row=>row.id===shipment.id?{...row,status:nextStatus,managerNote:note}:row))}setDecisionDialog('');setDecisionNote('');notify(decision==='approved'?`${shipment.id} approved and recorded.`:decision==='rejected'?`${shipment.id} rejected. The reason is recorded.`:`${shipment.id} returned to the executive for corrections.`,5000)};
  const approve=()=>decideShipment('approved');  const addShipment=async()=>{if(isSupabaseConfigured){const {data,error}=await supabase.from('shipments').insert({supplier_name:'',port_name:'Nhava Sheva'}).select('*,shipment_documents(*),shipment_items(*)').single();if(error){notify(`Could not create shipment: ${error.message}`);return}const fresh=toUiShipment(data);setRows(current=>[fresh,...current]);setActive(fresh.id);setTab('Review queue');setShowUpload(true);return}const n=rows.length+24811;const fresh={...seed[1],id:`SHP-${n}`,supplier:'New importer shipment',status:'In progress',docs:[],confidence:0,flag:'Upload the shipment documents to begin review.',invoice:'—'};persist([fresh,...rows]);setActive(fresh.id);setTab('Review queue');setShowUpload(true)};
  const onFiles=async(ev,type)=>{const selected=[...ev.target.files||[]];if(!selected.length||!shipment)return;const file=selected[0];const allowed=/\.(pdf|png|jpe?g|webp)$/i;if(file.size>20*1024*1024||!allowed.test(file.name)){notify('Choose a PDF, JPG, PNG or WebP under 20 MB.');ev.target.value='';return}if(isSupabaseConfigured){if(role!=='Executive'){notify('Only documentation executives can add documents.');return}if(shipment.documents?.some(d=>d.document_type===type)){notify('Remove the current file before uploading a replacement.');ev.target.value='';return}const objectPath=`${shipment.dbId}/${type}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const {error:uploadError}=await supabase.storage.from('shipment-documents').upload(objectPath,file,{contentType:file.type,upsert:false});if(uploadError){notify(`Upload failed: ${uploadError.message}`);return}const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());const sha256=[...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');const {error:rowError}=await supabase.from('shipment_documents').insert({shipment_id:shipment.dbId,document_type:type,object_path:objectPath,original_filename:file.name,mime_type:file.type,size_bytes:file.size,sha256});if(rowError){await supabase.storage.from('shipment-documents').remove([objectPath]);notify(`Document record failed: ${rowError.message}`);return}await refreshShipment(shipment.dbId);notify(`${docLabel[type]} uploaded privately. Extract it with AI or enter the fields manually.`);ev.target.value='';return}const label=docLabel[type];setUploads(v=>({...v,[shipment.id]:[...(v[shipment.id]||[]).filter(x=>x.documentType!==type),{file,documentType:type}]}));const next=rows.map(s=>s.id===shipment.id?{...s,docs:[...new Set([...s.docs,label])],status:'Needs review',flag:'Demo upload only. No AI extraction is running.'}:s);persist(next);setShowUpload(false);notify(`${label} added to ${shipment.id}.`);ev.target.value=''};
  const loadMore=async()=>{if(!isSupabaseConfigured||loadingMore)return;setLoadingMore(true);const start=rows.length;let request=supabase.from('shipments').select('*,shipment_documents(*),shipment_items(*),shipment_approval_events(*)').order('created_at',{ascending:false}).range(start,start+49);if(role==='Manager')request=request.in('status',['ready_for_approval','approved']);const {data,error}=await request;if(error)notify(`Could not load more shipments: ${error.message}`);else{const sourceRows=data||[];const ids=[...new Set(sourceRows.map(row=>row.submitted_by||row.created_by).filter(Boolean))];let people={};if(role==='Manager'&&ids.length){const {data:profiles, error:profileError}=await supabase.from('profiles').select('user_id,full_name,staff_code').in('user_id',ids);if(profileError)notify(`Executive identities could not be loaded: ${profileError.message}`);else people=Object.fromEntries((profiles||[]).map(person=>[person.user_id,person]))}const next=sourceRows.map(row=>toUiShipment(row,people[row.submitted_by||row.created_by]));setRows(current=>[...current,...next]);setHasMore(next.length===50)}setLoadingMore(false)};
