  const removeDocument=async(document)=>{if(!shipment||role!=='Executive'||!document)return;const label=docLabel[document.document_type]||document.documentType||'document';if(!window.confirm(`Remove ${document.original_filename||label} from ${shipment.id}? You can upload a replacement right after.`))return;if(!isSupabaseConfigured){setUploads(current=>({...current,[shipment.id]:(current[shipment.id]||[]).filter(file=>file.documentType!==document.documentType)}));persist(rows.map(row=>row.id===shipment.id?{...row,docs:row.docs.filter(name=>name!==label)}:row));notify('Document removed. Upload the correct file when ready.');return}const {error}=await supabase.from('shipment_documents').delete().eq('id',document.id);if(error){notify(`Could not remove file: ${error.message}`);return}const {error:storageError}=await supabase.storage.from('shipment-documents').remove([document.object_path]);await refreshShipment(shipment.dbId);notify(storageError?'Document removed. Private file cleanup will need a manager.':'Document removed. Upload the correct file when ready.',4500)};
